package com.campus.registration; import com.campus.registration.model.*; import com.campus.registration.service.*; import org.junit.jupiter.api.Test; import static org.junit.jupiter.api.Assertions.*; import java.util.*; class PrerequisiteGraphTest{@Test void prerequisiteComesFirst(){var g=new PrerequisiteGraph();g.add(new Course("B","B",3,1,List.of("A")));g.add(new Course("A","A",3,1,List.of()));var o=g.topologicalOrder();assertTrue(o.indexOf("A")<o.indexOf("B"));}}